/bin/bash -lc "mkdir -p /tmp/essay_docx && rm -rf /tmp/essay_docx/* && unzip -q /home/user/Desktop/Essay_Writing_English_for_uni.docx -d /tmp/essay_docx && python3 - <<'PY'
from xml.etree import ElementTree as ET
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
root=ET.parse('/tmp/essay_docx/word/document.xml').getroot()
paras=root.findall('.//w:body/w:p',ns)
for i,p in enumerate(paras):
    texts=''.join(t.text or '' for t in p.findall('.//w:t',ns))
    if p.find('./w:pPr/w:numPr',ns) is not None or 'References' in texts:
        print(i, texts[:180])
PY"

